blocks.text:
/* 회전한 뒤 그 방향으로 100 이동 */
transform: rotate(45deg) translateX(100px);

/* 오른쪽으로 100 이동한 뒤 회전 (다른 결과!) */
transform: translateX(100px) rotate(45deg);

/* A × B ≠ B × A (행렬 곱은 비가환) */
/* 점 기준 오른쪽 변환이 먼저 — M = T × R × S 면 크기→회전→이동 */
/* 흔한 관례: 크기 → 회전 → 이동 (SRT) */

// CSS / canvas matrix(a, b, c, d, e, f)
// [ a c e ]   x' = a·x + c·y + e
// [ b d f ]   y' = b·x + d·y + f
// [ 0 0 1 ]

// a, d = 크기·회전(대각)   b, c = 기울임·회전(비대각)   e, f = 이동
ctx.setTransform(a, b, c, d, e, f);   // canvas — 절대 설정
ctx.transform(a, b, c, d, e, f);      // 기존 변환에 곱함
// 회전: a=cos, b=sin, c=-sin, d=cos   |   순수 이동: a=d=1, b=c=0, e/f
// 3D 는 matrix3d(...) 16숫자(4×4)
